/**
 * CampusLoop Seed Data Surgical Rollback Script
 * 
 * Safely removes only records generated by batch 'campusloop-seed-2026-09'
 * without touching any genuine student accounts, real posts, or preexisting institutions.
 * 
 * Target identifier: id LIKE 'seed_202609_%'
 * 
 * Run: bun run scripts/campusloop-seeding/rollback.ts
 */

import { sql } from "drizzle-orm";
import { getDb } from "../../src/db";
import {
  academicResourceComments,
  academicResources,
  anonIdentityVault,
  comments,
  communities,
  communityMembers,
  eventRegistrations,
  events,
  pollOptions,
  pollVotes,
  posts,
  stories,
  userProfiles,
  votes,
} from "../../src/db/schema";
import { loadLocalEnv } from "../../src/lib/load-env";
import { BATCH_ID, ID_PREFIX } from "./config";

loadLocalEnv();

async function rollback() {
  console.log("================================================================");
  console.log(`⚠️ STARTING SURGICAL ROLLBACK FOR BATCH: ${BATCH_ID}`);
  console.log("================================================================\n");

  const db = getDb();
  const filter = sql`id LIKE ${ID_PREFIX + "%"}`;

  try {
    // 1. Delete poll interactions
    console.log("🗑️ Deleting seed poll votes & options...");
    await db.delete(pollVotes).where(filter);
    await db.delete(pollOptions).where(filter);

    // 2. Delete post upvotes
    console.log("🗑️ Deleting seed post upvotes...");
    await db.delete(votes).where(filter);

    // 3. Delete comments & replies
    console.log("🗑️ Deleting seed comments & nested replies...");
    await db.delete(comments).where(filter);

    // 4. Delete anon identity vault entries
    console.log("🗑️ Deleting seed anonymous vault entries...");
    await db.delete(anonIdentityVault).where(sql`id LIKE ${ID_PREFIX + "%"}`);

    // 5. Delete academic resources & comments
    console.log("🗑️ Deleting seed academic comments & resources...");
    await db.delete(academicResourceComments).where(filter);
    await db.delete(academicResources).where(filter);

    // 6. Delete event registrations & events
    console.log("🗑️ Deleting seed event registrations & events...");
    await db.delete(eventRegistrations).where(filter);
    await db.delete(events).where(filter);

    // 7. Delete stories
    console.log("🗑️ Deleting seed campus vibe stories...");
    await db.delete(stories).where(filter);

    // 8. Delete posts
    console.log("🗑️ Deleting seed feed posts...");
    await db.delete(posts).where(filter);

    // 9. Delete community memberships & communities
    console.log("🗑️ Deleting seed community members & communities...");
    await db.delete(communityMembers).where(filter);
    await db.delete(communities).where(filter);

    // 10. Delete seed user profiles
    console.log("🗑️ Deleting seed student personas...");
    await db.delete(userProfiles).where(filter);

    console.log("\n================================================================");
    console.log("✅ ROLLBACK COMPLETED WITH ZERO RESIDUAL SEED ARTIFACTS!");
    console.log("================================================================");
  } catch (err) {
    console.error("❌ Rollback failed:", err);
    process.exit(1);
  }
}

if (import.meta.main) {
  rollback()
    .then(() => process.exit(0))
    .catch((err) => {
      console.error(err);
      process.exit(1);
    });
}
